(() => {
  'use strict';
  const gameName=id=>({'valheim':'Valheim','7dtd':'7 Days to Die — TEST','forest':'The Forest — TEST'})[id]||'Herní server';
  const controllerOrigin=location.hostname==='127.0.0.1'?'':'https://yamahost.yamachat.eu';
  const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  let current=null,seq=0,timer=null,busy=false,selected=null;
  let detailRequest=0;
  const detailServer=new URL(location.href).searchParams.get('yh-server');
  const serverUrl=id=>`/?yh-server=${encodeURIComponent(id)}#yamahost`;
  let wizardServer=null;
  const profileNames=new Map();
  const rightLabels={owner:'Vlastník',host:'Může hostovat',manage:'Správa konfigurace a záloh',console:'Čtení konzole',delete:'Odstranění serveru',gameAdmin:'Správa hry / admin heslo'};
  const roleText=rights=>Object.keys(rightLabels).filter(k=>rights[k]).map(k=>rightLabels[k]).join(' · ')||'Hráč';
  async function namesFor(ids){
    const missing=[...new Set(ids.filter(id=>id&&!profileNames.has(id)))];
    if(missing.length){try{const client=YamaPortalIntegration.sharedClient(location.origin);const {data,error}=await client.from('profiles').select('id,display_name,username').in('id',missing);if(!error)for(const p of data||[])profileNames.set(p.id,p.display_name||p.username||'Člen serveru');}catch{}}
    return id=>profileNames.get(id)||'Člen serveru';
  }
  const statusText={offline:'Offline',hosting:'Hostování',starting:'Spouštění',online:'Online',stopping:'Ukládání a vypínání',syncing:'Synchronizace','host-unreachable':'Hostitel nedostupný',failed:'Chyba'};
  async function api(route,body){
    const client=YamaPortalIntegration.sharedClient(location.origin);const {data,error}=await client.auth.getSession();
    if(error||!data?.session)throw new Error('Přihlas se existujícím účtem YamaPortal.');
    const response=await fetch(controllerOrigin+'/api/yamahost/'+route,{method:body===undefined?'GET':'POST',headers:{Authorization:'Bearer '+data.session.access_token,...(body===undefined?{}:{'Content-Type':'application/json'})},body:body===undefined?undefined:JSON.stringify(body),cache:'no-store',redirect:'error'});
    const value=await response.json();if(!response.ok){const error=new Error(message(value.error));error.code=value.error;throw error;}return value;
  }
  function message(code){return ({UPLOAD_BUSY:'Právě probíhají jiné přenosy. Zálohování se pokusí pokračovat automaticky.',BACKUP_IN_PROGRESS:'Tuto nedokončenou zálohu právě používá aktivní hostitel. Počkej na dokončení.',ACCOUNT_STORAGE_FULL:'Vaše cloudové úložiště je zaplněné. Pro další ukládání uvolněte místo odstraněním nepotřebných záloh nebo serverů.',STORAGE_BUDGET_EXCEEDED:'Celková bezplatná kapacita služby je momentálně zaplněná. Existující data zůstávají zachovaná.',SERVER_STORAGE_UNAVAILABLE:'Na řídicí službě není dostatek volného místa pro bezpečné nahrání.',CURRENT_WORLD_PROTECTED:'Aktuální svět nelze odstranit jako historickou zálohu.',LAST_VERIFIED_COPY_PROTECTED:'Nejprve vyčkej na ověření aktuálního světa v cloudu. Poslední ověřenou kopii nelze smazat.',LAUNCHER_UPDATE_REQUIRED:'Pro tuto hru nebo formát zálohy potřebuješ aktuální launcher. Aktualizuj ho při vypnutém serveru a zachovej soukromou složku launcher/runtime.',RELEASE_PREPARATION:'Veřejné vydání se ověřuje. Tento účet zatím nemá přístup k hostování.',RATE_LIMITED:'Příliš mnoho požadavků. Počkej chvíli a zkus to znovu.',CONTROLLER_MIGRATED:'Servery byly přesunuty na yamahost.yamachat.eu. Otevři nové veřejné ovládání.',CLOUD_DELETE_ACCESS_REQUIRED:'Trvalé odstranění zatím nelze provést: přístup Oracle neumožňuje mazat zálohy. Server zůstal zachovaný.',CLOUD_DELETE_FAILED:'Mazání v Oracle se nezdařilo. Server a místní data zůstávají zachované.',BACKUP_BUSY:'Právě probíhá zálohování. Zkus odstranění za chvíli.',DELETE_NAME_CONFIRMATION_REQUIRED:'Napiš přesný název serveru včetně velkých a malých písmen.',DEVICE_OFFLINE:'Launcher není připojený. Spusť ho na vybraném počítači.',NOT_ENOUGH_RAM:'Hostitel nemá dost volné RAM pro vybranou hru (Valheim 6 GiB, 7 Days to Die 8 GiB, The Forest 4 GiB).',ALREADY_HOSTED:'Svět již má aktivního hostitele.',HOST_UNREACHABLE:'Předchozí hostitel je nedostupný. Je nutné rozhodnout o obnově poslední potvrzené verze.',FORBIDDEN:'K této akci nemáš oprávnění.',SERVER_LIMIT_REACHED:'Prostor účtu dovoluje nejvýše 3 servery.',BACKUP_LIMIT_REACHED:'Úložiště dosáhlo limitu záloh. Hosting nelze bezpečně zahájit.',PASSWORD_CONFIRMATION_OR_FORMAT:'Hesla musí být shodná, mít 8–64 znaků (písmena, číslice, _ nebo -) a nesmějí být součástí názvu serveru.',UNAUTHORIZED:'Přihlášení vypršelo. Přihlas se do Portalu.'})[code]||code||'Operace selhala.';}
  function notify(text){const out=document.querySelector('#yh-status');if(out)out.textContent=text;}
  function loadingPanel(server){return `<div class="yh-loading" role="status" aria-live="polite" aria-busy="true"><span class="yh-spinner" aria-hidden="true"></span><div><strong>${server?'Načítáme stránku serveru':'Načítáme tvoje servery'}</strong><p>${server?'Počkej prosím, ověřujeme přístup a načítáme stav serveru, konzoli a zálohy.':'Počkej prosím, připravujeme přehled tvých a sdílených serverů.'}</p><span>Chvilku strpení…</span></div></div>`;}
  function selectHostNavigation(){if(location.hash!=='#yamahost')return;for(const link of document.querySelectorAll('nav a')){const active=link.hash==='#yamahost';link.classList.toggle('active',active);if(active)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');}}
  function shell(){const page=document.querySelector('#page');page.hidden=false;page.innerHTML=`<section class="panel yh-panel"><div class="catalog-heading"><div><p class="eyebrow">YAMAHOST COMMUNITY</p><h2>${detailServer?'Načítám server…':'Jeden svět. Celá tvoje skupina.'}</h2><p class="muted">Server běží u oprávněného hostitele. Bez hostitele zůstává offline.</p></div></div><p class="notice">Herní server · hostování na počítači člena skupiny · 200 MB na účet sdílených všemi tvými servery · maximálně 3 servery · aktuální svět a nejvýše 3 historické zálohy na server.</p><div id="yh-storage"></div><p id="yh-status" role="status"></p><div class="yh-toolbar" ${detailServer?'hidden':''}><button class="primary" data-yh="create">Vytvořit server</button><button class="secondary" data-yh="guide">Jak založit server</button><button class="secondary" data-yh="accept">Přijmout pozvánku</button><button class="secondary" data-yh="refresh">Obnovit</button></div><div id="yh-list" ${detailServer?'hidden':''}>${detailServer?'':loadingPanel(false)}</div><div id="yh-detail">${detailServer?loadingPanel(true):''}</div></section><dialog id="yh-dialog"><button class="close" data-yh="close" aria-label="Zavřít">×</button><div id="yh-dialog-body"></div></dialog>`;}
  function dialog(html){const d=document.querySelector('#yh-dialog');document.querySelector('#yh-dialog-body').innerHTML=html;d.showModal();}
  function launcherGuide(){return `<p><a class="primary" href="${controllerOrigin}/downloads/yamahost-launcher-windows.zip" download>Stáhnout launcher pro Windows</a></p><ol><li>Otevři stažený ZIP a zvol <strong>Extrahovat vše</strong>.</li><li>V rozbalené složce spusť jediný soubor <strong>Spustit-YamaHost.cmd</strong>.</li><li>Vlož do jeho okna párovací kód z této stránky.</li></ol><p class="caption">Node.js je přibalený. Launcher nech otevřený na počítači, který má hostovat. Ostatní hráči ho pro samotné hraní nepotřebují.</p>`;}

  function guideMarkup(server,devices=[],signedIn=false){
    const online=devices.some(d=>d.online),paired=devices.length>0,ready=server?.phase==='online'&&(server.game!=='valheim'||!!server.joinCode),saved=server?.headVersion>0&&server?.cloudBackup?.state==='verified';
    const steps=[
      {icon:'＋',title:'Vytvoř server',text:'Vyber hru, název a herní heslo. Založením se hra ještě nespustí.',more:'Použij svůj existující účet YamaPortalu. Můžeš mít nejvýše 3 vlastní servery. U sdíleného serveru tento krok provádí jeho vlastník; tobě stačí pozvánka a právo hostovat.',done:!!server,status:server?'Server je založený':'Nejprve vytvoř nebo vyber server',action:signedIn?'<button class="secondary" data-yh="create">Vytvořit server</button>':'<a class="secondary" href="#profil" data-yh="guide-login">Přihlásit se</a>'},
      {icon:'↓',title:'Stáhni launcher',text:'Rozbal celý ZIP a spusť Spustit-YamaHost.cmd na hostitelském počítači.',more:'Node.js je přibalený. Oficiální SteamCMD a herní server se připraví až při prvním spuštění hry. Počítač potřebuje dostatek volné RAM a místa; neinstalujeme hru na společný cloudový server.',done:online,status:online?'Některý tvůj launcher právě běží':'Stažení samo z webu ověřit neumíme',action:'<button class="secondary" data-yh="download">Návod a stažení</button>'},
      {icon:'⇄',title:'Propoj počítač',text:'Kód z Propojit launcher vlož do jeho okna. Platí 5 minut a lze ho použít jednou.',more:'Počítač se propojí s tvým účtem. Hostovat pak může vlastní i sdílené servery, kde máš právo hostovat. Použitý či vypršelý kód nahraď novým. Propojený launcher při příštím spuštění nový kód nepotřebuje.',done:paired,status:paired?'Účet má propojený počítač':'Ještě není známý propojený launcher',action:signedIn?'<button class="secondary" data-yh="pair">Propojit launcher</button>':'<a class="secondary" href="#profil" data-yh="guide-login">Přihlásit se</a>'},
      {icon:'▶',title:'Spusť server',text:'Vyber svůj běžící launcher a potvrď spuštění v panelu. Poprvé může příprava trvat několik minut.',more:'Sleduj skutečný postup instalace a konzoli. Vytvořený herní proces ještě neznamená připravený server. Počkej na stav Online a údaje pro připojení vybrané hry.',done:ready,status:ready?'Server je aktuálně Online':server?.phase==='starting'?'Právě probíhá příprava':'Server se spouští až na tvůj pokyn',action:server?.permissions.host?'<button class="secondary" data-yh="guide-start">Přejít ke spuštění</button>':'<button class="secondary" data-yh="close">Vybrat server z přehledu</button>'},
      {icon:'♧',title:'Pozvi spoluhráče',text:'Pro hraní předej údaje pro připojení z karty serveru a herní heslo. Pro společnou správu použij pozvánku do skupiny.',more:'Samotní hráči launcher nepotřebují. Pozvánka do skupiny může povolit hostování podle nastavených práv. Kód hry není párovací kód launcheru; připojovací kód se po restartu může změnit.',done:false,status:ready?'Údaje pro připojení jsou připravené':'Připojení bude dostupné po spuštění',action:server?.permissions.owner?'<button class="secondary" data-yh="invite">Pozvat přítele</button>':ready?'<button class="secondary" data-yh="join">Údaje pro připojení</button>':''},
      {icon:'■',title:'Bezpečně ukonči a ulož',text:'Použij Ukončit a bezpečně uložit v panelu nebo Ctrl + C v aktivním okně launcheru. Počkej na dokončení.',more:'Launcher požádá hru o uložení, počká na potvrzení vypnutí a odešle svět do řídicí služby. Cloudovou kopii následně ověřuje panel. Aktuální svět a nejvýše 3 historické zálohy sdílejí 200 MB účtu vlastníka. Po uložení může jiný oprávněný člen spustit stejný svět. Okamžité automatické převzetí bez přerušení se neslibuje.',done:saved,status:saved?'Poslední potvrzená kopie je ověřená v cloudu':'Stav uložení sleduj v detailu serveru',action:server?'<button class="secondary" data-yh="guide-controls">Zpět k ovládání serveru</button>':''}
    ];
    return '<div class="yh-howto"><p class="eyebrow">YAMAHOST · NÁVOD</p><h2>Jak založit vlastní server</h2><p class="muted">'+(server?'Návod pro <strong>'+esc(server.name)+'</strong>.':'Od založení až po bezpečné uložení společného světa.')+' Návod nemusíš procházet při každém spuštění.</p><ol class="yh-guide-grid">'+steps.map((step,i)=>`<li class="yh-guide-step ${step.done?'done':''}"><div class="yh-guide-heading"><span class="yh-guide-number">${step.done?'✓':i+1}</span><span class="yh-guide-icon" aria-hidden="true">${step.icon}</span><h3>${step.title}</h3></div><p>${step.text}</p><p class="yh-guide-status">${step.status}</p><details><summary>Podrobnosti</summary><p>${step.more}</p></details>${step.action}</li>`).join('')+'</ol><p class="caption">Dokončené stavy vycházejí z aktuálních údajů panelu. Přítomnost ostatních hráčů ani stažení na konkrétním PC neodhadujeme.</p><button class="secondary" data-yh="close">Zavřít návod</button></div>';
  }
  function showGuide(){const server=detailServer?current?.servers.find(s=>s.id===detailServer):null;dialog(guideMarkup(server,current?.devices||[],!!current));}
  const gameTestNotice='<p class="notice yh-game-test" role="status"><strong>7 Days to Die — TEST</strong> · Základní hraní, ukládání a obnova byly ověřené. Připojení z jiné internetové sítě bez veřejné IP zatím není ověřené. PC verze, mapa Navezgane, bez modů.</p>';
  const createHelp='<details class="yh-create-help"><summary>Jak založit server · stručný návod</summary><dl><dt>Výběr hry</dt><dd>Vyber jednu z her dostupných v nabídce.</dd><dt>Hostování a propojení</dt><dd>Hra poběží na počítači se spuštěným launcherem. Po založení ho propojíš jednorázovým kódem a spuštění potvrdíš v panelu.</dd><dt>Ukládání</dt><dd>Po dokončeném herním uložení vznikají průběžné kopie; bezpečné vypnutí uloží a odešle poslední svět. 200 MB na účet, aktuální svět a nejvýše 3 historické zálohy na server.</dd><dt>Dostupnost</dt><dd>Bez hostitele je server offline. Jiný oprávněný člen může pokračovat z potvrzené kopie; nepřerušené automatické převzetí se neslibuje.</dd></dl><ol><li>Vytvoř server.</li><li>Stáhni a spusť launcher.</li><li>Propoj ho kódem z webu.</li><li>Potvrď spuštění a počkej na Online.</li><li>Pozvi přátele.</li><li>Ukončuj přes panel nebo Ctrl + C a vyčkej na uložení.</li></ol></details>';

  function wizardSteps(step){return '<ol class="yh-setup-steps" aria-label="Postup nastavení">'+['Server','Počítač','Hostování'].map((label,i)=>`<li class="${i+1===step?'current':i+1<step?'done':''}" ${i+1===step?'aria-current="step"':''}><span>${i+1<step?'✓':i+1}</span>${label}</li>`).join('')+'</ol>';}
  async function setupWizard(id){
    wizardServer=id;selected=id;current=await api('servers');const s=current.servers.find(s=>s.id===id);
    if(!s)throw new Error('Server už není dostupný.');
    const online=current.devices.filter(d=>d.online&&(s.game==='valheim'||d.games?.includes(s.game)));
    if(s.state!=='offline'){document.querySelector('#yh-dialog').close();await detail(id);notify('Server už má hostitele. Jeho stav najdeš níže.');return;}
    if(online.length){
      dialog(`${wizardSteps(3)}<h2>Vše je připravené</h2><p>Server <strong>${esc(s.name)}</strong> je založený a launcher je připojený.</p><label>Na kterém počítači hostovat?<select id="yh-setup-device">${online.map(d=>`<option value="${esc(d.id)}">${esc(d.label)}</option>`).join('')}</select></label><p>Po spuštění launcher připraví ${esc(gameName(s.game))} a načte poslední uložený svět. První příprava může trvat několik minut.</p><p class="notice">Počítač i launcher musí během hraní zůstat zapnuté.</p><div class="yh-toolbar"><button class="primary" data-yh="setup-start">Spustit hostování</button><button class="secondary" data-yh="close">Zatím nespouštět</button></div><p class="yh-form-error" role="status"></p>`);
    }else{
      dialog(`${wizardSteps(2)}<h2>Propoj svůj počítač</h2><p>Server <strong>${esc(s.name)}</strong> je založený. Teď připoj počítač, který ho bude hostovat.</p>${s.game==='7dtd'?'<p class="notice">Pro 7 Days to Die — TEST potřebuješ launcher 0.2.0 nebo novější. Starší launcher podporuje pouze Valheim. Aktualizuj ho při vypnutém serveru a zachovej složku launcher/runtime. Pokud nová kopie žádá kód, propoj ji přes Návod a stažení.</p>':current.devices.length?'<p class="notice">Dříve propojený launcher stačí spustit. Pokud jsi ho stáhl do nové složky a žádá kód, propoj ho znovu přes Návod a stažení.</p>':launcherGuide()}<div class="yh-toolbar">${current.devices.length?'<button class="secondary" data-yh="download">Návod a stažení</button>':'<button class="primary" data-yh="setup-pair">Zobrazit párovací kód</button>'}<button class="primary" data-yh="setup-check">Launcher už běží – pokračovat</button><button class="secondary" data-yh="close">Dokončit později</button></div><p class="caption">Samotné propojení ještě nespustí hru. Hostování potvrdíš až v posledním kroku.</p><p class="yh-form-error" role="status"></p>`);
    }
  }
  async function load(){if(location.hash!=='#yamahost'||busy)return;busy=true;try{
    const toolbar=document.querySelector('.yh-panel > .yh-toolbar');
    if(toolbar&&!toolbar.querySelector('[data-yh="download"]')){const b=document.createElement('button');b.className='secondary';b.dataset.yh='download';b.textContent='Stáhnout launcher';toolbar.append(b);}
    const result=await api('servers');current=result;renderStorage(result.storage);
    selectHostNavigation();
    const group=(title,items)=>`<h3>${title}</h3><div class="yh-server-grid">${items.length?items.map(s=>`<article class="yh-server-card"><span class="pill">${esc(statusText[s.phase]||s.phase)}</span><h3>${esc(s.name)}</h3><p>${esc(gameName(s.game))} · ${esc(s.version||'verze zatím nezjištěna')}</p><p>Potvrzená verze světa: ${s.headVersion} · historické zálohy: ${s.storage.historicalBackups??Math.max(0,s.storage.backups-1)}/3</p><a class="secondary yh-open-server" href="${serverUrl(s.id)}" target="_blank" rel="noopener" aria-label="Otevřít server ${esc(s.name)} v nové záložce">Otevřít server <span aria-hidden="true">↗</span></a></article>`).join(''):'<p class="muted">Zatím žádné servery.</p>'}</div>`;
    document.querySelector('#yh-list').innerHTML=group('Moje servery',result.servers.filter(s=>s.permissions.owner))+group('Sdílené se mnou',result.servers.filter(s=>!s.permissions.owner));
    if(detailServer){selected=detailServer;document.querySelector('#yh-list').hidden=true;document.querySelector('.yh-panel > .yh-toolbar').hidden=true;await detail(detailServer,false);if(document.querySelector('.yh-backups'))await showBackups(detailServer);}
  }catch(error){
    const target=document.querySelector(detailServer?'#yh-detail':'#yh-list');
    if(error.message==='Společný účet není připravený.'){notify('Připravujeme přihlášení…');if(!target.querySelector('#yh-console'))target.innerHTML=loadingPanel(!!detailServer);return;}
    if(detailServer&&['FORBIDDEN','WORLD_NOT_FOUND','SERVER_NOT_FOUND'].includes(error.code)){
      document.title='Server není dostupný – YamaHost';const heading=document.querySelector('.yh-panel .catalog-heading h2');if(heading)heading.textContent='Server není dostupný';
      notify('');target.innerHTML='<div class="yh-load-error" role="status"><strong>K tomuto serveru nemáš přístup</strong><p>Přihlášený účet není členem tohoto serveru, nebo server už neexistuje. Své vlastní a sdílené servery najdeš v přehledu.</p><a class="secondary" href="/#yamahost">← Přehled mých serverů</a></div>';return;
    }
    notify(error.message);if(!target.querySelector('#yh-console'))target.innerHTML=`<div class="yh-load-error" role="alert"><strong>Načítání se nepodařilo</strong><p>${esc(error.message)}</p><button class="secondary" data-yh="refresh">Zkusit znovu</button></div>`;
  }finally{busy=false;}}
  async function detail(id,reset=true){
    if(!detailServer)return;
    if(!document.querySelector('.yh-back-to-servers')){const back=document.createElement('a');back.href='/#yamahost';back.className='secondary yh-back-to-servers';back.textContent='← Přehled serverů';document.querySelector('.yh-panel .catalog-heading').before(back);}
    if(reset||selected!==id){seq=0;selected=id;}
    const request=++detailRequest;const s=await api('servers/'+id);if(request!==detailRequest)return;const host=document.querySelector('#yh-detail');
    document.title=s.name+' – YamaHost';
    const heading=document.querySelector('.yh-panel .catalog-heading h2');if(heading)heading.textContent=s.name;
    if(!document.querySelector('.yh-back-to-servers')){const back=document.createElement('a');back.href='/#yamahost';back.className='secondary yh-back-to-servers';back.textContent='← Přehled serverů';document.querySelector('.yh-panel .catalog-heading').before(back);}
    if(reset||!host.querySelector('#yh-console'))host.innerHTML=`<section class="yh-detail"><div id="yh-server-head"></div><div id="yh-progress" hidden></div><div class="yh-toolbar" id="yh-controls"></div><div id="yh-connect"></div><div id="yh-console-pane"><h3 id="yh-log-title"></h3><p id="yh-log-state" class="yh-log-state" role="status"></p><p class="caption">Zobrazuje posledních 200 záznamů tohoto serveru. Zde je skutečný log tohoto serveru; textové příkazy z webu zatím nejsou povolené.</p><pre id="yh-console" aria-label="Log herního serveru"></pre></div><div class="yh-toolbar" id="yh-management"></div><div id="yh-extra"></div></section>`;
    host.querySelector('#yh-server-head').innerHTML=`<h2>${esc(s.name)}</h2><p><strong>${esc(statusText[s.phase]||s.phase)}</strong> · hostitel: ${esc(s.host||'nikdo')} · hráči: ${s.players??'nezjištěno'}</p><p>Poslední potvrzená verze: ${s.headVersion} · úložiště: ${mb(s.storage.bytes)} · RAM procesu: ${s.memoryBytes==null?'nezjištěno':(s.memoryBytes/1_000_000).toFixed(0)+' MB'}</p>`;
    if(s.lastError){const error=document.createElement('p');error.className='yh-launch-error';error.setAttribute('role','status');error.textContent=({'SERVER_INSTALL_FAILED':'Instalace herního serveru se nezdařila. Herní proces se nespustil, proto zatím nemá vlastní log.','NOT_ENOUGH_DISK_SPACE':'Na hostitelském počítači není dost místa.','NOT_ENOUGH_RAM':'Na hostitelském počítači není dost volné paměti.'}[s.lastError]||'Launcher akci nedokončil: '+s.lastError);host.querySelector('#yh-server-head').append(error);}
    if(['starting','stopping','syncing'].includes(s.phase)){const progress=document.createElement('div');progress.className='yh-loading yh-game-progress';progress.setAttribute('role','status');progress.innerHTML=`<span class="yh-spinner" aria-hidden="true"></span><div><strong>${({starting:'Server se spouští — ještě chvíli počkej',stopping:'Server se bezpečně ukládá a zastavuje',syncing:'Ověřujeme a přenášíme uložený svět'})[s.phase]}</strong><p>${s.phase==='starting'?(s.game!=='valheim'?'Údaje pro připojení se zobrazí po načtení světa a registraci serveru. První spuštění může trvat několik minut.':'Připojovací kód se zobrazí až po potvrzení, že je server připravený. První spuštění může trvat několik minut.'):'Nezavírej launcher. Počkej na dokončení ukládání a synchronizace.'}</p></div>`;host.querySelector('#yh-server-head').append(progress);}
    const eligibleDevices=(current?.devices||[]).filter(d=>s.game==='valheim'||d.games?.includes(s.game));
    const deviceOptions=eligibleDevices.map(d=>`<option value="${d.id}" ${d.online?'':'disabled'}>${esc(d.label)}${d.online?'':' – offline'}</option>`).join('');
    const cloud=document.createElement('p');cloud.className='notice';
    cloud.textContent='Oracle záloha poslední verze: '+({verified:'ověřena nahráním a zpětným stažením',pending:'čeká na nahrání',failed:'nahrání selhalo, místní kopie je zachována','no-backup':'svět zatím nemá uloženou zálohu','not-configured':'přístup zatím není nastavený'}[s.cloudBackup?.state]||'stav nezjištěn');
    host.querySelector('#yh-server-head').append(cloud);
    if(s.game==='7dtd')host.querySelector('#yh-server-head').insertAdjacentHTML('beforeend',gameTestNotice);if(s.game==='forest')host.querySelector('#yh-server-head').insertAdjacentHTML('beforeend','<p class="notice">The Forest — TEST. Hostitel potřebuje právo hostovat i spravovat hru; běžní hráči tato oprávnění nepotřebují. Ověřeno místní připojení a obnova světa. Internetové připojení bez veřejné IP není zatím zajištěné a může vyžadovat přesměrování UDP portů. Postavu a inventář ukládej ve hře u přístřešku; svět ukládá server průběžně a při bezpečném ukončení.</p>');
    host.querySelector('#yh-controls').innerHTML=(s.state==='offline'||s.canResumeAfterFailure)&&s.permissions.host&&(s.game!=='forest'||s.permissions.gameAdmin)?`<select id="yh-device" aria-label="Hostitelský počítač">${deviceOptions||'<option>Žádný připojený launcher</option>'}</select><button class="primary" data-yh="start" ${eligibleDevices.some(d=>d.online)?'':'disabled'}>${s.canResumeAfterFailure?'Spustit z poslední zálohy':'Spustit server'}</button>`:s.state==='hosting'&&(s.permissions.manage||current?.devices.some(d=>d.id===s.deviceId))?'<button class="yh-stop" data-yh="stop"><span aria-hidden="true">⏹</span> Ukončit a bezpečně uložit</button><button class="yh-restart" data-yh="restart"><span aria-hidden="true">↻</span> Restartovat</button>':'';
    const controls=host.querySelector('#yh-controls');controls.classList.toggle('yh-runtime-actions',s.state==='hosting');
    host.querySelector('#yh-unavailable-stop')?.remove();
    if(s.state==='host-unreachable'&&(s.permissions.host||s.permissions.manage)){
      const fallback=document.createElement('div');fallback.id='yh-unavailable-stop';fallback.className='yh-runtime-actions';
      fallback.innerHTML='<button class="yh-stop" disabled><span aria-hidden="true">⏹</span> Ukončit a bezpečně uložit</button><p class="caption">Launcher není dostupný. Uložení z webu nyní nelze potvrdit; obnova po výpadku je samostatná akce.</p>';
      host.querySelector('#yh-console').after(fallback);
    }
    if(s.state==='hosting')host.querySelector('#yh-console').after(controls);else host.querySelector('#yh-connect').before(controls);
    host.querySelector('#yh-connect').innerHTML=s.phase==='online'&&s.game==='forest'?`<div class="yh-join-card"><div><span class="yh-join-label">The Forest — TEST</span><strong>${esc(s.name)}</strong><p>Multiplayer → Join Game → Dedicated (LAN / Internet). Herní port ${s.config.port}, dotazovací port ${s.config.queryPort}. Vzdálené připojení zatím neověřeno.</p></div><button class="secondary" data-yh="join">Zobrazit herní heslo</button></div>`:s.phase==='online'&&s.game==='7dtd'?`<div class="yh-join-card"><div><span class="yh-join-label">7 Days to Die — TEST · vyhledej server ve hře</span><strong class="yh-join-code">${esc(s.name)}</strong><span class="yh-join-help">TEST · PC · Navezgane · bez modů. Vzdálené připojení bez veřejné IP se teprve ověřuje.</span></div><button class="secondary" data-yh="join">Zobrazit herní heslo</button></div>`:s.phase==='online'?`<div class="yh-join-card"><div><span class="yh-join-label">Připojovací kód do Valheimu</span><strong class="yh-join-code">${esc(s.joinCode||'Čekáme na kód…')}</strong><span class="yh-join-help">Ve hře zvol připojení pomocí kódu.</span></div><div class="yh-join-buttons"><button class="secondary" data-yh="copy-join" data-code="${esc(s.joinCode||'')}" ${s.joinCode?'':'disabled'}><span aria-hidden="true">⧉</span> Kopírovat kód</button><button class="secondary" data-yh="join">Zobrazit herní heslo</button></div></div>`:!eligibleDevices.some(d=>d.online)?'<p class="notice">Nejdřív propojíš počítač. Klikni na <strong>Propojit launcher</strong>, spusť na hostitelském PC <strong>Spustit-YamaHost.cmd</strong> a zadej do něj kód z webu. Potom se zde počítač objeví.</p>':'<p class="muted">Připojení bude dostupné po spuštění a registraci serveru.</p>';
    host.querySelector('#yh-management').innerHTML=`<button class="secondary" data-yh="members">Členové</button><button class="secondary" data-yh="history">Historie</button>${s.permissions.owner?'<button class="secondary" data-yh="invite">Pozvat přítele</button>':''}${s.permissions.host||s.permissions.manage?'<button class="secondary" data-yh="backups">Zálohy a stažení</button>':''}${s.permissions.manage?'<button class="secondary" data-yh="config">Konfigurace</button>':''}${s.game==='forest'&&s.permissions.gameAdmin?'<button class="secondary" data-yh="game-admin">Správa hry / admin heslo</button>':''}${s.state==='host-unreachable'&&s.permissions.owner?'<button class="secondary danger" data-yh="recover">Obnovit po výpadku hostitele</button>':''}`;
    const guideButton=document.createElement('button');guideButton.className='secondary';guideButton.dataset.yh='guide';guideButton.textContent='Jak založit server';host.querySelector('#yh-management').append(guideButton);
    const progressBox=host.querySelector('#yh-progress');const showProgress=s.state==='hosting'&&s.phase!=='online'&&s.progress?.message;progressBox.hidden=!showProgress&&!s.lastError;progressBox.innerHTML=s.lastError?'<p class="yh-guide-error" role="alert">Akce se nezdařila: '+esc(message(s.lastError))+'</p>':showProgress?'<div class="yh-start-progress" role="status"><span class="yh-spinner" aria-hidden="true"></span><div><strong>'+esc(s.progress.message)+'</strong>'+(Number.isFinite(s.progress.percent)?'<progress max="100" value="'+s.progress.percent+'" aria-label="Skutečný průběh instalace"></progress>':'')+'<p class="caption">Stav hlásí připojený launcher. Vyčkej na Online.</p></div></div>':'';
    const commandButton=document.createElement('button');commandButton.className='secondary';commandButton.dataset.yh='commands';commandButton.innerHTML='<span aria-hidden="true">⌨</span> Příkazová konzole';host.querySelector('#yh-management').prepend(commandButton);
    if(s.state==='offline'&&s.permissions.host){const guide=document.createElement('button');guide.className='secondary';guide.dataset.yh='setup-resume';guide.textContent=s.headVersion===0?'Dokončit nastavení krok za krokem':'Průvodce spuštěním';host.querySelector('#yh-controls').append(guide);}
    if(s.permissions.delete){const remove=document.createElement('button');remove.className='yh-delete-button';remove.dataset.yh='delete';remove.textContent='🗑 Odstranit server';host.querySelector('#yh-management').append(remove);}
    if(s.host){const name=await namesFor([s.host]);const head=host.querySelector('#yh-server-head > p');if(head)head.innerHTML=`<strong>${esc(statusText[s.phase]||s.phase)}</strong> · hostitel: ${esc(name(s.host))} · hráči: ${s.players??'nezjištěno'}`;}
    if(s.phase!=='online'&&current?.devices.length&&!eligibleDevices.some(d=>d.online))host.querySelector('#yh-connect').innerHTML='<p class="notice">Launcher už máš propojený, ale právě neběží. Spusť ho a nech jeho okno otevřené. Nový párovací kód nepotřebuješ.</p><button class="secondary" data-yh="download">Návod a stažení launcheru</button>';
    if(['7dtd','forest'].includes(s.game)&&current?.devices.some(d=>d.online)&&!eligibleDevices.some(d=>d.online))host.querySelector('#yh-connect').innerHTML='<p class="notice">Připojený launcher tuto hru zatím nepodporuje. Stáhni nejnovější launcher a aktualizuj ho při vypnutém serveru se zachováním launcher/runtime.</p><button class="secondary" data-yh="download">Návod a stažení launcheru</button>';
    const launcherActions=document.createElement('div');launcherActions.className='yh-toolbar';
    launcherActions.innerHTML='<button class="secondary" data-yh="pair">Propojit launcher</button>';
    const launcherGuideButton=host.querySelector('#yh-connect > button[data-yh="download"]');
    if(launcherGuideButton)launcherActions.append(launcherGuideButton);
    host.querySelector('#yh-connect').append(launcherActions);
    host.querySelector('#yh-log-title').textContent=(s.state==='offline'?'Historie konzole — ':'Konzole — ')+s.name;
    if(s.permissions.console){
      const log=host.querySelector('#yh-console');
      if(log.dataset.server!==id||log.dataset.epoch!==String(s.epoch)){log.textContent='';log.dataset.server=id;log.dataset.epoch=String(s.epoch);log.dataset.lastAt='';seq=0;}
      const data=await api(`servers/${id}/console?after=${seq}`);
      if(selected!==id||!log.isConnected||log.dataset.server!==id)return;
      let added=false;for(const line of data.lines){if(line.seq<=seq)continue;if(log.dataset.placeholder){log.textContent='';delete log.dataset.placeholder;}log.textContent+=line.line+'\n';seq=line.seq;log.dataset.lastAt=String(line.at);added=true;}
      log.textContent=log.textContent.slice(-100000);if(added)log.scrollTop=log.scrollHeight;
      if(!seq){log.textContent=s.state==='offline'?'Tento server zatím nemá žádné záznamy.':'Čekáme na první záznam tohoto serveru.';log.dataset.placeholder='true';}
      const time=log.dataset.lastAt?new Intl.DateTimeFormat('cs-CZ',{dateStyle:'medium',timeStyle:'medium',timeZone:'Europe/Prague'}).format(new Date(Number(log.dataset.lastAt))):'zatím žádný';
      host.querySelector('#yh-log-state').textContent=(s.state==='offline'?'Server je vypnutý. Níže je uložená historie, nikoli živé události. ':'Události patří pouze serveru '+s.name+'. ')+ 'Poslední záznam: '+time+'.';
    }else{host.querySelector('#yh-console').textContent='Nemáš oprávnění ke konzoli.';host.querySelector('#yh-log-state').textContent='';}
  }
  async function action(button){const op=button.dataset.yh,id=selected;
    if(op==='commands'){
      const s=await api('servers/'+id);
      document.querySelector('#yh-extra').innerHTML=`<section class="yh-command-panel"><h3>Příkazová konzole — ${esc(s.name)}</h3><p>Příkazy z této konzole budou určené pouze serveru <strong>${esc(s.name)}</strong>.</p><p class="notice">${s.game==='7dtd'?'Příkazy z webu zatím nejsou v testovací verzi povolené. Launcher používá místní herní konzoli pro bezpečné ukládání a vypnutí.':'Odesílání příkazů pro Valheim zatím není připojené. Běžný dedikovaný server nečte příkazy z tohoto logu; pro vzdálené ovládání musíme doplnit serverovou podporu.'}</p><label for="yh-command-input">Příkaz pro tento server</label><div class="yh-command-input"><input id="yh-command-input" type="text" placeholder="Zde bude možné zadat podporovaný příkaz" disabled><button class="secondary" disabled>Odeslat příkaz</button></div><p class="caption">Základní nastavení najdeš v Konfiguraci. Spuštění, bezpečné uložení a restart fungují přes vlastní tlačítka.</p></section>`;return;
    }
    if(['members','history','backups'].includes(op)){document.querySelector('#yh-extra').innerHTML='<p class="muted" role="status">Načítám…</p>';}
    if(op==='download-backup'){
      const client=YamaPortalIntegration.sharedClient(location.origin);const {data,error}=await client.auth.getSession();if(error||!data?.session)throw new Error('Přihlas se do YamaPortalu.');
      const response=await fetch(`${controllerOrigin}/api/yamahost/servers/${encodeURIComponent(id)}/backups/${encodeURIComponent(button.dataset.snapshot)}/download`,{headers:{Authorization:'Bearer '+data.session.access_token},cache:'no-store',redirect:'error'});
      if(!response.ok){const value=await response.json();throw new Error(message(value.error));}
      const blob=await response.blob(),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=/filename="([A-Za-z0-9._-]+)"/.exec(response.headers.get('Content-Disposition')||'')?.[1]||'YamaHost-zaloha.zip';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);notify('Záloha je připravená ke stažení jako ZIP.');return;
    }
    if(op==='delete'){
      const s=await api('servers/'+id);
      if(s.state!=='offline')throw new Error('Nejdřív server bezpečně zastav a ulož. Běžící server nelze odstranit.');
      dialog(`<h2>Odstranit server</h2><p>Server <strong>${esc(s.name)}</strong> bude trvale odstraněn včetně uloženého světa a záloh v YamaHostu. Tuto akci nelze vrátit.</p><form id="yh-delete"><label>Pro potvrzení napiš přesný název: <strong>${esc(s.name)}</strong><input id="yh-delete-name" name="name" autocomplete="off" data-expected="${esc(s.name)}" required></label><div class="yh-toolbar"><button class="yh-delete-button" type="submit" disabled>Odstranit server</button><button class="secondary" type="button" data-yh="close">Zrušit</button></div><p class="yh-form-error" role="status"></p></form>`);return;
    }
    if(op==='copy-join'){const server=await api('servers/'+id);if(server.phase!=='online'||!/^\d{6}$/.test(server.joinCode||'')){await detail(id,false);notify('Server zatím nemá aktivní připojovací kód. Počkej na dokončení spuštění.');return;}try{await navigator.clipboard.writeText(server.joinCode);await detail(id,false);notify('Aktuální připojovací kód byl zkopírovaný.');}catch{notify('Kód se nepodařilo zkopírovat. Označ ho a zkopíruj ručně.');}return;}
    if(op==='setup-resume'){await setupWizard(id);return;}
    if(op==='setup-check'){await setupWizard(wizardServer);if(!current.devices.some(d=>d.online))document.querySelector('#yh-dialog .yh-form-error').textContent='Launcher zatím není připojený. Nech jeho okno otevřené a zkus kontrolu znovu.';return;}
    if(op==='setup-back'){await setupWizard(wizardServer||detailServer||selected);return;}
    if(op==='launcher-check'){
      if(wizardServer){await setupWizard(wizardServer);if(!current.devices.some(d=>d.online))document.querySelector('#yh-dialog .yh-form-error').textContent='Launcher zatím není připojený. Pokud čeká na kód, zobraz si nový párovací kód.';return;}
      await load();dialog(`<h2>${current?.devices.some(d=>d.online)?'Launcher je připojený':'Čekáme na launcher'}</h2><p>${current?.devices.some(d=>d.online)?'Můžeš zavřít toto okno a vybrat server k hostování.':'Nech launcher otevřený. Pokud žádá kód, nejdřív ho propoj.'}</p><div class="yh-toolbar"><button class="secondary" data-yh="download">Zpět k návodu</button><button class="primary" data-yh="close">Zavřít</button></div>`);return;
    }
    if(op==='setup-pair'){const p=await api('pair',(detailServer||wizardServer)?{worldId:detailServer||wizardServer}:{});dialog(`${wizardServer?wizardSteps(2):''}<h2>Zadej kód do launcheru</h2><p class="yh-code">${esc(p.code)}</p><p>Kód platí 5 minut. Vlož ho do otevřeného launcheru a stiskni Enter.</p><div class="yh-toolbar"><button class="primary" data-yh="launcher-check">Propojeno – pokračovat</button><button class="secondary" data-yh="setup-pair">Vygenerovat nový kód</button><button class="secondary" data-yh="download">← Zpět k návodu</button><button class="secondary" data-yh="close">Dokončit později</button></div><p class="yh-form-error" role="status"></p>`);return;}
    if(op==='setup-start'){await api(`servers/${wizardServer}/start`,{deviceId:document.querySelector('#yh-setup-device').value});selected=wizardServer;wizardServer=null;document.querySelector('#yh-dialog').close();notify('Hostování se spouští.');await load();dialog(`<h2>Hostování se spouští</h2><p>Stav, připojovací kód a konzoli najdeš v samostatné záložce serveru.</p><a class="primary" href="${serverUrl(selected)}" target="_blank" rel="noopener">Otevřít server v nové záložce ↗</a>`);return;}
    if(op==='close'){wizardServer=null;document.querySelector('#yh-dialog').close();return;}
    if(op==='download'){if(!wizardServer&&detailServer)wizardServer=detailServer;dialog(`${wizardServer?wizardSteps(2):''}<h2>Launcher pro tvůj počítač</h2>${launcherGuide()}<p class="notice">Nově stažený launcher potřebuje vlastní propojení. Pokud jeho okno žádá párovací kód, zobraz si ho tlačítkem níže. Dříve propojený launcher nový kód nepotřebuje.</p><div class="yh-toolbar"><button class="primary" data-yh="setup-pair">Zobrazit párovací kód</button><button class="primary" data-yh="launcher-check">Launcher je propojený – pokračovat</button>${wizardServer?'<button class="secondary" data-yh="setup-back">← Zpět na nastavení počítače</button>':''}<button class="secondary" data-yh="close">Dokončit později</button></div><p class="yh-form-error" role="status"></p>`);return;}
    if(op==='guide'){showGuide();return;}
    if(op==='guide-login'){document.querySelector('#yh-dialog').close();return;}
    if(op==='guide-start'){document.querySelector('#yh-dialog').close();await setupWizard(selected||detailServer);return;}
    if(op==='guide-controls'){document.querySelector('#yh-dialog').close();document.querySelector('#yh-controls')?.scrollIntoView({block:'center',behavior:'smooth'});return;}
    if(op==='refresh'){await load();return;}
    if(op==='detail'){await detail(button.dataset.id);return;}
    if(op==='create'){wizardServer=null;dialog(`${wizardSteps(1)}<h2>Založ svůj server</h2><p>Nejdřív vyber název a herní heslo. Potom tě provedeme propojením počítače a prvním spuštěním.</p>${createHelp}<form id="yh-create"><label>Název serveru<input name="name" required minlength="3" maxlength="60" placeholder="Například Náš společný svět"></label><label>Hra<select name="game">${(current?.games||['valheim']).map(game=>`<option value="${esc(game)}">${esc(gameName(game))}</option>`).join('')}</select></label>${current?.games?.some(g=>['7dtd','forest'].includes(g))?'<div id="yh-create-game-info" hidden>'+gameTestNotice+'</div>':''}<label>Herní heslo<input name="password" type="password" required minlength="8" maxlength="64" autocomplete="new-password"></label><label>Heslo ještě jednou<input name="confirmation" type="password" required minlength="8" maxlength="64" autocomplete="new-password"></label><p class="caption">8–64 znaků: písmena, číslice, pomlčka nebo podtržítko. Použij jiné heslo než k účtu YamaPortal.</p><p class="notice">Založením se server ještě nespustí. Na účtu můžeš mít nejvýše 3 servery.</p><button class="primary">Založit server a pokračovat</button><p class="yh-form-error" role="status"></p></form>`);return;}
    if(op==='pair'){const p=await api('pair',{});dialog(`<h2>Propojit počítač</h2>${launcherGuide()}<h3>Tvůj párovací kód</h3><p class="yh-code">${esc(p.code)}</p><p>Platí 5 minut. Propojení umožní tomuto počítači hostovat servery podle tvých práv. Automatické hostování je ve výchozím stavu vypnuté.</p>`);return;}
    if(op==='accept'){dialog('<h2>Přijmout pozvánku</h2><form id="yh-accept"><label>Kód pozvánky<input name="code" required></label><button class="primary">Přijmout</button><p class="yh-form-error" role="status"></p></form>');return;}
    if(op==='start'){await api(`servers/${id}/start`,{deviceId:document.querySelector('#yh-device').value});notify('Požadavek odeslán připojenému launcheru.');}
    if(op==='stop'||op==='restart'){await api(`servers/${id}/${op}`,{});notify('Launcher provede bezpečné uložení a '+(op==='stop'?'vypnutí.':'restart.'));}
    if(op==='game-admin'){const a=await api(`servers/${id}/game-admin`);dialog(`<h2>Správa hry The Forest</h2><p>Admin heslo: <strong>${esc(a.adminPassword)}</strong></p><p>Vlož ho do ADMIN PASSWORD při připojení. Správce může v herním chatu zadat /save pro uložení světa. Bezpečné ukončení v panelu ukládá svět automaticky.</p><p>Postavu a inventář ukládej ve hře u přístřešku. Záloha světa nenahrazuje osobní uložení hráče.</p>`);return;}
    if(op==='join'){const j=await api(`servers/${id}/join`);dialog(`<h2>Připojení do ${esc(gameName(j.game))}</h2>${j.game!=='valheim'?'<p>Ve hře vyhledej server: <strong>'+esc(j.name)+'</strong>. Připojení z jiné sítě se ještě ověřuje.</p>':'<p>Kód: <strong>'+esc(j.joinCode||'zatím není dostupný')+'</strong></p>'}<p>Heslo: <strong>${esc(j.password)}</strong></p><p>Sdílej pouze se členy své skupiny.</p>`);}
    if(op==='invite'){dialog('<h2>Pozvat člena skupiny</h2><form id="yh-invite"><label><input type="checkbox" name="host"> Smí hostovat</label><label><input type="checkbox" name="console"> Smí číst konzoli</label><label><input type="checkbox" name="manage"> Smí spravovat konfiguraci a zálohy</label><label><input type="checkbox" name="gameAdmin"> Smí spravovat hru a zobrazit admin heslo (nutné i k hostování The Forest)</label><button class="primary">Vytvořit jednorázovou pozvánku</button><p class="yh-form-error" role="status"></p></form>');return;}
    if(op==='history'){const d=await api(`servers/${id}/history`);document.querySelector('#yh-extra').innerHTML='<h3>Historie</h3>'+d.events.map(e=>`<p>${esc(new Date(e.at).toLocaleString())} · ${esc(e.action)} · ${esc(e.actor)}</p>`).join('');}
    if(op==='members'){
      const [d,s]=await Promise.all([api(`servers/${id}/members`),api(`servers/${id}`)]);const name=await namesFor(d.members.map(m=>m.actor));
      const members=d.members.sort((a,b)=>Number(!!b.rights.owner)-Number(!!a.rights.owner)||name(a.actor).localeCompare(name(b.actor),'cs'));
      document.querySelector('#yh-extra').innerHTML=`<div class="yh-members-heading"><h3>Členové <span class="yh-member-count">${members.length}</span></h3><label for="yh-member-search">Vyhledat člena<input id="yh-member-search" type="search" placeholder="Přezdívka nebo ID" autocomplete="off"></label></div><div class="yh-members" role="list" aria-label="Členové serveru">${members.map(m=>`<article class="yh-member" role="listitem" data-member-search="${esc((name(m.actor)+' '+m.actor).toLocaleLowerCase('cs'))}"><div class="yh-member-info"><strong class="yh-member-name">${esc(name(m.actor))}</strong><small class="yh-member-id">ID: ${esc(m.actor)}</small><div class="yh-member-roles">${(Object.keys(rightLabels).filter(k=>m.rights[k]).length?Object.keys(rightLabels).filter(k=>m.rights[k]).map(k=>rightLabels[k]):['Hráč']).map(label=>`<span class="yh-role">${esc(label)}</span>`).join('')}</div></div>${s.permissions.owner&&!m.rights.owner?`<button class="secondary" data-yh="rights" data-actor="${esc(m.actor)}" aria-label="Upravit oprávnění: ${esc(name(m.actor))}">Upravit oprávnění</button>`:''}</article>`).join('')}</div><p id="yh-members-empty" class="muted" role="status" hidden>Žádný člen neodpovídá hledání.</p>`;
    }
    if(op==='rights'){const d=await api(`servers/${id}/members`);const m=d.members.find(m=>m.actor===button.dataset.actor);if(!m)throw new Error('Člen již není dostupný.');const name=await namesFor([m.actor]);dialog(`<h2>Oprávnění člena</h2><div class="yh-member-identity"><strong class="yh-member-name">${esc(name(m.actor))}</strong><small class="yh-member-id">ID: ${esc(m.actor)}</small></div><form id="yh-rights"><input type="hidden" name="actor" value="${esc(m.actor)}"><label><input type="checkbox" name="host" ${m.rights.host?'checked':''}> Smí hostovat na svém zařízení</label><label><input type="checkbox" name="console" ${m.rights.console?'checked':''}> Smí číst konzoli</label><label><input type="checkbox" name="manage" ${m.rights.manage?'checked':''}> Smí spravovat konfiguraci a zálohy</label><label><input type="checkbox" name="gameAdmin" ${m.rights.gameAdmin?'checked':''}> Smí spravovat hru a zobrazit admin heslo</label><label><input type="checkbox" name="delete" ${m.rights.delete?'checked':''}> Smí odstranit server</label><p>Bez těchto oprávnění zůstává hráčem. Oprávnění aktivního hostitele lze změnit až po zastavení serveru.</p><button class="primary">Uložit oprávnění</button><p class="yh-form-error" role="status"></p></form>`);return;}
    if(op==='backups'){await showBackups(id);return;}
    if(op==='delete-backup'&&confirm('Trvale odstranit tuto historickou nebo nedokončenou zálohu? Aktuální svět zůstane zachovaný.')){await api(`servers/${id}/backups/${button.dataset.snapshot}/delete`,{confirmed:true});await load();await showBackups(id);return;}
    if(op==='restore'&&confirm('Obnovit vybranou zálohu jako novou aktuální verzi? Server musí být vypnutý. Novější historie zůstane zachovaná.'))await api(`servers/${id}/restore`,{snapshotId:button.dataset.snapshot,acknowledgeDataLoss:true});
    if(op==='recover'&&confirm('Předchozí hostitel je nedostupný. Obnovit poslední potvrzenou verzi? Nepřenesené změny mohou chybět a staré hostování bude zneplatněno.'))await api(`servers/${id}/recover`,{acknowledgeDataLoss:true});
    if(op==='config'){const s=await api('servers/'+id);dialog(`<h2>Konfigurace</h2><form id="yh-config"><label>Název serveru<input name="name" value="${esc(s.name)}" required minlength="3" maxlength="60"></label><p>${s.game==='forest'?'The Forest — TEST · serverové rozšíření pro bezpečné ukládání':s.game==='7dtd'?'7 Days to Die — TEST · PC · Navezgane · bez modů':'Valheim · crossplay zapnutý'} · změny jen při vypnutém serveru.</p><button class="primary">Uložit</button><p class="yh-form-error" role="status"></p></form>`);return;}
    if(selected)await detail(selected,false);
  }
  document.addEventListener('click',event=>{const b=event.target.closest('[data-yh]');if(!b)return;b.disabled=true;void action(b).catch(e=>{const out=document.querySelector('#yh-dialog[open] .yh-form-error');if(out)out.textContent=e.message;else notify(e.message);}).finally(()=>{b.disabled=false;});});
  document.addEventListener('input',event=>{if(event.target.id!=='yh-member-search')return;const query=event.target.value.trim().toLocaleLowerCase('cs');let visible=0;for(const row of document.querySelectorAll('[data-member-search]')){row.hidden=!row.dataset.memberSearch.includes(query);if(!row.hidden)visible++;}const empty=document.querySelector('#yh-members-empty');if(empty)empty.hidden=visible>0;});
  document.addEventListener('input',event=>{const form=event.target.closest('#yh-delete');if(!form)return;const field=form.querySelector('[name=name]');form.querySelector('[type=submit]').disabled=field.value!==field.dataset.expected;});
  document.addEventListener('submit',event=>{const f=event.target;if(!f.id.startsWith('yh-'))return;event.preventDefault();const values=Object.fromEntries(new FormData(f));const submit=f.querySelector('button');submit.disabled=true;void(async()=>{
    if(f.id==='yh-create'){if(values.password!==values.confirmation)throw new Error('Hesla se neshodují.');const s=await api('servers',values);selected=s.id;await load();await setupWizard(s.id);return;}
    if(f.id==='yh-delete'){await api(`servers/${selected}/delete`,{name:values.name,confirmed:true});document.querySelector('#yh-dialog').close();clearInterval(timer);document.querySelector('#yh-detail').innerHTML='<section class="yh-detail"><h2>Server byl trvale odstraněn</h2><p>Server už není dostupný.</p><a class="secondary" href="/#yamahost">← Přehled serverů</a></section>';selected=null;return;}
    if(f.id==='yh-accept'){const s=await api('invitations/accept',values);selected=s.id;}
    if(f.id==='yh-invite'){const p=await api(`servers/${selected}/invitations`,{host:!!values.host,console:!!values.console,manage:!!values.manage,gameAdmin:!!values.gameAdmin});dialog(`<h2>Pozvánka do skupiny</h2><p>Člen se přihlásí vlastním účtem Portalu a přijme tento kód:</p><p class="yh-code">${esc(p.code)}</p><p>Platnost 24 hodin, jednorázové použití.</p>`);return;}
    if(f.id==='yh-config')await api(`servers/${selected}/config`,values);
    if(f.id==='yh-rights')await api(`servers/${selected}/members`,{actor:values.actor,rights:{host:!!values.host,console:!!values.console,manage:!!values.manage,delete:!!values.delete,gameAdmin:!!values.gameAdmin}});
    document.querySelector('#yh-dialog').close();await load();if(selected)await detail(selected);
  })().catch(e=>{const out=f.querySelector('.yh-form-error');if(out)out.textContent=e.message;}).finally(()=>{submit.disabled=false;});});

  const mb=bytes=>new Intl.NumberFormat('cs-CZ',{maximumFractionDigits:2}).format(bytes/1_000_000)+' MB';
  function renderStorage(storage){
    const host=document.querySelector('#yh-storage');if(!host||!storage)return;
    const percent=Math.min(100,Math.floor(storage.usedBytes*100/storage.limitBytes));const level=percent>=95?'full':percent>=80?'warning':'normal';
    const expanded=!!host.querySelector('details[open]');
    host.innerHTML=`<section class="yh-storage-card ${level}" aria-label="Cloudové úložiště"><div class="yh-storage-heading"><strong>▤ Cloudové úložiště</strong><span>YamaHost Free</span></div><div class="yh-storage-total"><strong>${mb(storage.usedBytes)}</strong><span>/ 200 MB</span><b>${percent} %</b></div><progress value="${storage.usedBytes}" max="200000000" aria-label="Zaplnění cloudového úložiště">${percent} %</progress><div class="yh-storage-summary"><span>Využito ${mb(storage.usedBytes)}</span><span>Volné místo ${mb(storage.freeBytes)}</span></div><p class="caption">${storage.usedBytes.toLocaleString('cs-CZ')} / 200 000 000 bajtů · Servery ${storage.servers.length}/3 · 3 historické zálohy na server${storage.inFlightBytes?' · Probíhající přenosy (max.) '+mb(storage.inFlightBytes):''}</p>${percent>=95?'<p class="yh-storage-alert" role="status">'+(storage.freeBytes===0?'Vaše cloudové úložiště je zaplněné. Pro další ukládání uvolněte místo odstraněním nepotřebných záloh nebo serverů.':'Cloudové úložiště je téměř zaplněné. Uvolni místo odstraněním nepotřebných záloh nebo serverů.')+'</p>':''}<details><summary>Spotřeba jednotlivých serverů</summary>${storage.servers.length?'<ul>'+storage.servers.map(server=>`<li><a href="${serverUrl(server.id)}">${esc(server.name)}</a><strong>${mb(server.usedBytes)}</strong><small>Aktuální svět ${mb(server.currentBytes)} · Historie a nedokončená uložení ${mb(server.usedBytes-server.currentBytes)}</small></li>`).join('')+'</ul>':'<p class="caption">Zatím nemáš vlastní server. Prostor se předem nerezervuje.</p>'}</details><p class="caption">Sdílené servery čerpají úložiště svého vlastníka. Aktuální svět se započítává pouze jednou.</p></section>`;
    if(expanded)host.querySelector('details').open=true;
  }
  async function showBackups(id){
    const [data,server]=await Promise.all([api(`servers/${id}/backups`),api('servers/'+id)]);const name=await namesFor(data.backups.map(b=>b.actor));
    const date=new Intl.DateTimeFormat('cs-CZ',{dateStyle:'medium',timeStyle:'medium',timeZone:'Europe/Prague'});
    const target=document.querySelector('#yh-extra');if(!target)return;
    target.innerHTML='<h3>Svět a historické zálohy</h3><p class="caption">Aktuální svět a nejvýše 3 historické zálohy. Uvedena skutečná uložená velikost; časy jsou v českém čase.</p><div class="yh-backups">'+(data.backups.length?data.backups.map(b=>`<article class="yh-backup"><div class="yh-member-info"><strong class="yh-member-name">${b.savedAt==null?'Nepotvrzené uložení':esc(date.format(new Date(b.savedAt)))}</strong><p class="yh-backup-author">Uložil <strong>${esc(b.actor?name(b.actor):'Neznámý uživatel')}</strong></p><small class="yh-member-id">ID uživatele: ${esc(b.actor||'nedostupné')}</small><small class="yh-member-id">ID zálohy: ${esc(b.id)}</small><div class="yh-member-roles"><span class="yh-role">${b.isCurrent?'Aktuální svět':b.committed?'Historická záloha':'Nedokončená záloha'}</span><span class="yh-role">Verze ${b.base+1}</span><span class="yh-role" title="${b.size} bajtů">${mb(b.size)}</span></div></div><div class="yh-backup-actions">${server.permissions.host&&b.committed?`<button class="secondary" data-yh="download-backup" data-snapshot="${esc(b.id)}">↓ Stáhnout zálohu ZIP</button>`:''}${server.permissions.manage&&b.committed&&!b.isCurrent?`<button class="secondary" data-yh="restore" data-snapshot="${esc(b.id)}">Obnovit jako novou verzi</button>`:''}${server.permissions.manage&&!b.isCurrent?`<button class="secondary yh-delete-button" data-yh="delete-backup" data-snapshot="${esc(b.id)}">Odstranit zálohu</button>`:''}</div></article>`).join(''):'<p class="muted">Zatím není uložená žádná záloha.</p>')+'</div>';
  }

  function show(){clearInterval(timer);if(location.hash!=='#yamahost')return;selectHostNavigation();window.YamaModuleHost?.hide();shell();seq=0;void load();timer=setInterval(()=>{if(location.hash==='#yamahost')void load();else clearInterval(timer);},5000);}
  document.addEventListener('change',event=>{if(event.target?.matches?.('#yh-create select[name=game]')){const info=document.querySelector('#yh-create-game-info');if(info){info.hidden=!['7dtd','forest'].includes(event.target.value);info.innerHTML=event.target.value==='forest'?'<p class="notice">The Forest — TEST. Místní připojení a obnova světa ověřeny; vzdálené připojení bez veřejné IP zatím neověřeno. Rozšíření pro bezpečné ukládání instaluje launcher pouze na server. Hostitel potřebuje práva hostovat i spravovat hru.</p>':gameTestNotice;}}});
  window.YamaHostPanel={show};
  const nav=document.querySelector('nav');if(nav&&!nav.querySelector('[href="#yamahost"]')){const link=document.createElement('a');link.href='#yamahost';link.innerHTML='<svg class="yh-nav-icon" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.2" stroke-linecap="round" aria-hidden="true"><rect x="2" y="2" width="12" height="5" rx="1"/><rect x="2" y="9" width="12" height="5" rx="1"/><path d="M4 4.5h.01M7 4.5h4M4 11.5h.01M7 11.5h4"/></svg><span>YamaHost</span>';nav.append(link);}
  // Existing Portal renderer remains authoritative for all other routes.
  window.addEventListener('hashchange',()=>{if(location.hash==='#yamahost')show();else clearInterval(timer);});
  document.addEventListener('yama-account-state',()=>{if(location.hash==='#yamahost'){selected=null;current=null;show();}});
  if(location.hash==='#yamahost')show();
})();

